
use anyhow::{Result, bail}; use reed_solomon_erasure::galois_8::ReedSolomon; const DATA_SHARDS: usize = 223; const PARITY_SHARDS: usize = 32; const BLOCK_SIZE: usize = DATA_SHARDS + PARITY_SHARDS; pub fn encode_ecc(data: &[u8]) -> Vec<u8> { let rs = ReedSolomon::new(DATA_SHARDS, PARITY_SHARDS).unwrap(); let mut result = Vec::new(); for chunk in data.chunks(DATA_SHARDS) { let mut shards: Vec<Vec<u8>> = vec![vec![0; 1]; BLOCK_SIZE]; for (i, &byte) in chunk.iter().enumerate() { shards[i][0] = byte; } rs.encode(&mut shards).unwrap(); for shard in shards { result.push(shard[0]); } } result.extend_from_slice(&(data.len() as u32).to_le_bytes()); result } pub fn decode_ecc(data: &[u8]) -> Result<Vec<u8>> { if data.len() < 4 { bail!("ECC data too short"); } let original_len = u32::from_le_bytes(data[data.len()-4..].try_into()?) as usize; let ecc_data = &data[..data.len()-4]; let rs = ReedSolomon::new(DATA_SHARDS, PARITY_SHARDS).unwrap(); let mut result = Vec::with_capacity(original_len); for chunk in ecc_data.chunks(BLOCK_SIZE) { if chunk.len() != BLOCK_SIZE { break; } let mut shards: Vec<Vec<u8>> = chunk.iter().map(|&b| vec![b]).collect(); let _ = rs.reconstruct(&mut shards); for i in 0..DATA_SHARDS { if result.len() < original_len { result.push(shards[i][0]); } } } Ok(result) }